// Resolve variant prices from Shopify Admin API
const shopify = await shopifyClientFor(req.platform!);
let originalTotalMinor = 0;
const currency = "USD";

for (const variantId of selected_variant_external_ids) {
  try {
    const variantGid = `gid://shopify/ProductVariant/${variantId}`;
    const variantData = await shopify.graphql<ProductVariantQueryResult>(
      `query GetVariant($id: ID!) {
         productVariant(id: $id) {
           id
           price
           availableForSale
           legacyResourceId
         }
       }`,
      { id: variantGid },
    );
    if (variantData.productVariant) {
      originalTotalMinor += money.toMinorUnits(variantData.productVariant.price, currency);
    }
  } catch (_err) {
    // best-effort; proceed with partial total
  }
}

new_string:
// Resolve variant prices from Shopify Admin API using provided GIDs (no local construction)
const shopify = await shopifyClientFor(req.platform!);
let originalTotalMinor = 0;
const currency = "USD";

for (let i = 0; i < selected_variant_external_ids.length; i++) {
  const variantId = selected_variant_external_ids[i];
  const variantGid = selected_variant_gids[i]; // sourced from live_variant_gid on component
  if (!variantId || !variantGid) continue;
  try {
    const variantData = await shopify.graphql<ProductVariantQueryResult>(
      `query GetVariant($id: ID!) {
         productVariant(id: $id) {
           id
           price
           availableForSale
           legacyResourceId
         }
       }`,
      { id: variantGid },
    );
    if (variantData.productVariant) {
      originalTotalMinor += money.toMinorUnits(variantData.productVariant.price, currency);
    }
  } catch (_err) {
    // best-effort; proceed with partial total
  }
}
